const tokenise = (text) =>
  Array.isArray(text)
    ? text
    : Array.from(text).map((k) =>
        k === " "
          ? "SPACE"
          : k === "\b"
            ? "BACKSPACE"
            : k === "\n"
              ? "ENTER"
              : k.toUpperCase(),
      );
function chapter(world, title, kind, lesson, rows, goals, props, extra = {}) {
  return {
    id: CHAPTERS.length,
    world,
    title,
    kind,
    lesson,
    props,
    phases: rows.map((row, i) => ({
      keys: tokenise(row),
      goal: goals[i],
      response:
        extra.responses?.[i] ||
        [
          "有变化啦，再试一下！",
          "快完成了，继续慢慢来。",
          "这是你亲手完成的！",
        ][i],
    })),
    ...extra,
  };
}
const CHAPTERS = [];
function add(...args) {
  CHAPTERS.push(chapter(...args));
}
